import { SegmentedControl } from '@kerfjs/ui/segmented-control';
import { Toolbar } from '@kerfjs/ui/toolbar';
import '@kerfjs/ui/layout.css';
import './view-choice.css';

export type WorkspaceView = 'board' | 'list' | 'timeline';
export type WorkspaceAction = { type: 'workspace.view.set'; view: WorkspaceView };
const options = [
  { value: 'board', label: 'Board' },
  { value: 'list', label: 'List' },
  { value: 'timeline', label: 'Timeline' },
];
export function WorkspaceViewChoice({ value, dispatch }: {
  value: WorkspaceView; dispatch: (action: WorkspaceAction) => void;
}) {
  return <div className="kui-layout">
    <Toolbar aria-label="Workspace tools" className="workspace-tools">
      <SegmentedControl aria-label="Workspace view" value={value} options={options}
        onChange={(next: string) => {
          if (next === 'board' || next === 'list' || next === 'timeline') {
            dispatch({ type: 'workspace.view.set', view: next });
          }
        }} />
    </Toolbar>
  </div>;
}
// The primitive owns radio-group semantics, roving focus, and arrow-key selection.
// The application owns the selected view and any persistence.
